		A[state] = (((num_t)((i * j) % m) / (num_t)m) * (num_t)100.0) + (num_t)10.0;
		Q[state] = (num_t)0.0;
	});

	// Initialize R
	// for (i = 0; i < n; i++)
	//   for (j = 0; j < n; j++)
