//  - Outer loops over k and j are expressed using Noarr traversers (for_dims).
//  - We precompute 1/R[k,k] once per column to replace many divisions by
//    cheaper multiplications.
//  - All inner loops over i use traversers on column views, so they walk
//    contiguous memory (good cache and SIMD behaviour).
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	#pragma scop
	// Drive the outer loop over k using a traverser of R.
	// R has dimensions 'k' (row) and 'j' (column).
	traverser(R).template for_dims<'k'>([&](auto trav_k) {
		// trav_k has 'k' fixed; extract its value
		auto state_k = trav_k.state();
		std::size_t k = get_index<'k'>(state_k);

		// k-th column views of A and Q: A[:, k], Q[:, k]
		// These are 1D structures in dimension 'i' only.
		auto A_col_k = A ^ fix<'j'>(k);
		auto Q_col_k = Q ^ fix<'j'>(k);

		// --------------------------------------------------------------------
		// 1) Compute squared 2-norm of k-th column of A:
		//      nrm = sum_i A[i][k] * A[i][k]
		// --------------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		traverser(A_col_k).for_each([&](auto s_i) {
			num_t a_ik = A_col_k[s_i];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		num_t r_kk = std::sqrt(nrm);
		R[idx<'k', 'j'>(k, k)] = r_kk;

		// Precompute reciprocal to avoid a division per element in Q update.
		// (Numerically very close to original code: 1 division + M multiplies
		//  instead of M divisions.)
		num_t inv_r_kk = (num_t)1.0 / r_kk;

		// --------------------------------------------------------------------
		// 2) Normalize k-th column: Q[i][k] = A[i][k] / R[k][k]
		//    (implemented as Q[i][k] = A[i][k] * inv_r_kk)
		// --------------------------------------------------------------------
		traverser(A_col_k, Q_col_k).for_each([&](auto s_i) {
			Q_col_k[s_i] = A_col_k[s_i] * inv_r_kk;
		});

		// --------------------------------------------------------------------
		// 3) Orthogonalize remaining columns j > k:
		//      R[k][j] = sum_i Q[i][k] * A[i][j]
		//      A[i][j] = A[i][j] - Q[i][k] * R[k][j]
		//
		// We drive the j-loop using for_dims<'j'> on the traverser with
		// fixed 'k'. This iterates j in [0, N), and we explicitly skip
		// j <= k to preserve the upper-triangular structure.
		// --------------------------------------------------------------------
		trav_k.template for_dims<'j'>([&](auto trav_kj) {
			auto state_kj = trav_kj.state();
			std::size_t j = get_index<'j'>(state_kj);

			// Only process trailing columns j > k
			if (j <= k)
				return;

			// j-th column view of A: A[:, j]
			auto A_col_j = A ^ fix<'j'>(j);

			// 3a) r_kj = sum_i Q[i][k] * A[i][j]
			num_t r_kj = (num_t)0.0;

			traverser(Q_col_k, A_col_j).for_each([&](auto s_i) {
				r_kj += Q_col_k[s_i] * A_col_j[s_i];
			});

			// Store R[k][j]. trav_kj acts as a state with 'k' and 'j'.
			R[trav_kj] = r_kj;

			// 3b) A[:, j] -= Q[:, k] * R[k][j]
			traverser(Q_col_k, A_col_j).for_each([&](auto s_i) {
				A_col_j[s_i] = A_col_j[s_i] - Q_col_k[s_i] * r_kj;
			});
		});
	});
	#pragma endscop
