namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// A, Q:  M x N  (i x j)
	//
	// Original code used (j_vec ^ i_vec), which makes 'j' contiguous (row-major).
	// The Gram–Schmidt kernel works with *columns* A[:,k], A[:,j], Q[:,k],
