	DEFINE_PROTO_STRUCT(q_layout, i_vec ^ j_vec);

	// R: N x N (k x j)
	//
	// Keep R row-major: 'j' contiguous for a fixed 'k'.  This already matches
	// the access pattern R[k, j] with j varying fastest in the algorithm.
	DEFINE_PROTO_STRUCT(r_layout, j_vec ^ k_vec);
} tuning;


