// Main computational kernel --------------------------------------------------
// QR Decomposition with Modified Gram-Schmidt
//
// Optimizations compared to the baseline version:
//   - A and Q are stored column-major (i contiguous) via tuning.a_layout/q_layout,
//     which matches the column-wise access pattern and improves locality.
//   - Q[:,k] normalization uses a precomputed reciprocal 1/R[k,k] to replace
//     M divisions with M multiplications plus one division.
//   - All loop nests (over k, j, i) are expressed using Noarr traversers,
//     keeping index management layout-agnostic and enabling further tuning.
//
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	auto m = A | get_length<'i'>();
	auto n = A | get_length<'j'>();

	(void)m; // m is not explicitly needed, traversal takes care of bounds

	#pragma scop
	// Outer loop over k (columns). We drive it through the 'k' dimension of R.
	// This preserves the sequential dependence between successive k-steps.
	traverser(R).template for_dims<'k'>([&](auto k_trav) {
		auto k_state = k_trav.state();
		std::size_t k = get_index<'k'>(k_state);

		// Column views A[:,k] and Q[:,k]
		auto A_col_k = A ^ fix<'j'>(k);
		auto Q_col_k = Q ^ fix<'j'>(k);

		// ---------------------------------------------------------------------
		// 1) Compute squared 2-norm of column k of A:
		//      nrm = sum_i A[i,k] * A[i,k]
		// ---------------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		traverser(A_col_k).for_each([&](auto state_i) {
			num_t a_ik = A_col_k[state_i];
			nrm += a_ik * a_ik;
		});

		// ---------------------------------------------------------------------
		// 2) Normalize column k into Q[:,k] and set R[k,k]:
		//      R[k][k] = sqrt(nrm);
		//      Q[i][k] = A[i][k] / R[k][k];
		//
		//    We explicitly compute inv_r_kk = 1 / R[k,k] and use
		//      Q[i,k] = A[i,k] * inv_r_kk
		//    which is equivalent up to rounding, but cheaper than a
		//    division per element.
		// ---------------------------------------------------------------------
		num_t r_kk = std::sqrt(nrm);
		R[idx<'k', 'j'>(k, k)] = r_kk;

		// Precompute reciprocal of R[k,k] (strength reduction).
		num_t inv_r_kk = (num_t)1.0 / r_kk;

		traverser(A_col_k, Q_col_k).for_each([&](auto state_i) {
			Q_col_k[state_i] = A_col_k[state_i] * inv_r_kk;
		});

		// If there are no trailing columns, we are done for this k.
		if (k + 1 >= n)
			return;

		// ---------------------------------------------------------------------
		// 3) For each trailing column j > k:
		//      R[k][j] = Q[:,k]^T * A[:,j]
		//      A[:,j]  = A[:,j] - Q[:,k] * R[k][j]
		//
