		//    is sliced to only include columns j in (k+1 .. n-1).
		//    This keeps the j-range exact (no extra work for j ≤ k) while
		//    still using pure Noarr traversers for the iteration.
		// ---------------------------------------------------------------------

		// View of row k of R, restricted to columns j = k+1 .. n-1.
		//   - fix<'k'>(k)   : select row k      (dimension 'j' remains)
		//   - slice<'j'>(..) : drop the first k+1 entries, keep the tail
		//                      of length (n - (k+1)).
		auto R_row_k_tail =
			(R ^ fix<'k'>(k)) ^
			slice<'j'>(k + 1, n - (k + 1));

