			// The 'j' index in this state runs from 0 to (n - k - 2).
			// Map it back to the absolute column index j_abs = k+1 + j_rel.
			std::size_t j_rel = get_index<'j'>(state_j);
			std::size_t j_abs = j_rel + k + 1;

			// j-th column view of A: A[:, j_abs]
			auto A_col_j = A ^ fix<'j'>(j_abs);

			// --------------------------------------------------------------
			// 3a) r_kj = Q[:,k]^T * A[:,j_abs]
			// --------------------------------------------------------------
